// Aviso a Marisa de una venta grande (HU-09).
//
// El umbral NO esta en el flujo: vive en la variable de n8n UMBRAL_VENTA_GRANDE
// (Settings > Variables). Asi se cambia sin tocar el flujo.
// El importe es el de la API: no se recalcula.
// La API da las fechas como AAAA-MM-DD; en los mensajes van como dia/mes/año.
const fechaES = (f) => {
  const t = String(f ?? '').split('-');
  return t.length === 3 ? t[2].slice(0, 2) + '/' + t[1] + '/' + t[0] : String(f ?? '');
};
const entrada = $input.first().json ?? {};
const d = entrada.datos ?? entrada;

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = (s) => '<p>' + escapar(s).replace(/\n/g, '<br>') + '</p>';

// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
// El umbral viene del fichero de configuracion (lo anade el nodo de cruce).
const umbral = Number($json.umbral ?? 200);

const cuerpo = [
  'Ojo, esta venta es grande:',
  '',
  'Concepto: ' + (d.concepto ?? ''),
  'Importe: ' + euros(d.importe),
  'Forma de pago: ' + (d.forma_pago ?? ''),
  'Fecha: ' + fechaES(d.fecha),
  '',
  'Umbral de aviso: ' + euros(umbral),
].join('\n');

return [{
  json: {
    canal: 'email',
    email: emailTienda,
    asunto: 'Venta grande · ' + euros(d.importe),
    cuerpo,
    cuerpo_html: html(cuerpo),
    importe: d.importe ?? null,
    umbral,
  },
}];

// Lee la configuracion de data/config.csv (clave,valor).
// Vive en un fichero y no en el flujo: se cambia sin tocar el flujo.
const config = {};
for (const item of $('Parsear configuracion').all()) {
  const clave = String(item.json?.clave ?? '').trim();
  const valor = String(item.json?.valor ?? '').trim();
  if (clave) config[clave] = valor;
}
const umbral = Number(config.UMBRAL_VENTA_GRANDE || 200);

// La venta viene del disparador.
const ventas = $('Datos de la venta').all().map((i) => i.json);
return ventas.map((v) => ({ json: { ...v, umbral } }));
